import{_ as e,o as i,c as t,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"Ceph Developer Monthly 2021-03-03","description":"","frontmatter":{"title":"Ceph Developer Monthly 2021-03-03","date":"2021-03-03T00:00:00.000Z","updated":"2021-04-21T00:00:00.000Z","tags":["Ceph","分布式存储","性能优化","测试改进","Windows支持"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Developer_Monthly_2021-03-03.md","filePath":"posts/2021/Ceph_Developer_Monthly_2021-03-03.md","lastUpdated":1780460162000}'),r={name:"posts/2021/Ceph_Developer_Monthly_2021-03-03.md"};function a(n,l,s,h,u,p){return i(),t("div",null,[...l[0]||(l[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-ceph分布式存储系统优化与测试改进" tabindex="-1">会议主题：Ceph分布式存储系统优化与测试改进 <a class="header-anchor" href="#会议主题-ceph分布式存储系统优化与测试改进" aria-label="Permalink to &quot;会议主题：Ceph分布式存储系统优化与测试改进&quot;">​</a></h4><h4 id="日期-2021年3月" tabindex="-1">日期：2021年3月 <a class="header-anchor" href="#日期-2021年3月" aria-label="Permalink to &quot;日期：2021年3月&quot;">​</a></h4><h4 id="参会人员-kyle-vigor-以及其他ceph研发和测试团队成员" tabindex="-1">参会人员：Kyle Vigor, 以及其他Ceph研发和测试团队成员 <a class="header-anchor" href="#参会人员-kyle-vigor-以及其他ceph研发和测试团队成员" aria-label="Permalink to &quot;参会人员：Kyle Vigor, 以及其他Ceph研发和测试团队成员&quot;">​</a></h4><h4 id="主要议题" tabindex="-1">主要议题： <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题：&quot;">​</a></h4><ol><li><p><strong>Ceph RGW性能优化与配置简化</strong></p><ul><li><strong>讨论内容</strong>： <ul><li>讨论了通过预设的Erasure Coded（EC）配置文件简化用户配置，提高性能和易用性。</li><li>探讨了自动加载预设配置文件，并让用户直接使用的可能性。</li><li>讨论了通过RGW客户端根据不同EC配置文件动态调整参数，优化性能。</li><li>提出了为特定池设置提示或属性，以优化存储分配和管理的想法。</li></ul></li><li><strong>决定事项</strong>： <ul><li>需要进一步讨论和定义具体的EC配置文件参数。</li><li>需要研究如何在RGW和BlueStore中实现这些优化策略。</li></ul></li><li><strong>后续行动计划</strong>： <ul><li>创建跟踪问题（tracker issues）和任务分解，具体实施优化策略。</li><li>与开发团队合作，确保优化策略的技术可行性和实施细节。</li></ul></li></ul></li><li><p><strong>构建与测试优化</strong></p><ul><li><strong>讨论内容</strong>： <ul><li>讨论了优化测试执行和提高测试覆盖率，包括改进测试的并行执行和减少测试间的重复。</li><li>探讨了减少测试环境的设置和重置时间，以及减少日志收集的开销。</li><li>讨论了使用Ninja作为构建工具的可能性，以提高构建速度。</li></ul></li><li><strong>决定事项</strong>： <ul><li>需要进一步分析和优化测试执行流程。</li><li>需要评估Ninja作为构建工具的效果和可行性。</li></ul></li><li><strong>后续行动计划</strong>： <ul><li>开展暑期项目，专注于测试优化和构建效率提升。</li><li>探索使用Ninja和其他构建工具的可能性，并进行实际测试。</li></ul></li></ul></li><li><p><strong>Telemetry意识提升</strong></p><ul><li><strong>讨论内容</strong>： <ul><li>讨论了如何在用户界面和命令行接口中提高Telemetry的可见性和用户参与度。</li><li>探讨了如何通过教育和宣传来减少用户对Telemetry的疑虑。</li></ul></li><li><strong>决定事项</strong>： <ul><li>需在主要升级时提醒用户启用Telemetry。</li><li>需要通过CLI和文档宣传Telemetry的好处和实际应用案例。</li></ul></li><li><strong>后续行动计划</strong>： <ul><li>在主要升级时通过CLI提醒用户启用Telemetry。</li><li>制作宣传材料，展示Telemetry的实际应用和好处。</li></ul></li></ul></li><li><p><strong>Windows支持</strong></p><ul><li><strong>讨论内容</strong>： <ul><li>讨论了Windows支持的进展，包括构建和测试流程的自动化。</li><li>探讨了如何通过CI集成来确保Windows支持的稳定性和可靠性。</li></ul></li><li><strong>决定事项</strong>： <ul><li>需要进一步完善Windows支持的CI流程。</li><li>需要确保Windows支持的测试覆盖率和质量。</li></ul></li><li><strong>后续行动计划</strong>： <ul><li>与CI团队合作，完善Windows支持的CI流程。</li><li>增加Windows支持的测试用例，确保质量。</li></ul></li></ul></li></ol><h4 id="总结" tabindex="-1">总结： <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结：&quot;">​</a></h4><p>本次会议主要聚焦于Ceph RGW的性能优化、构建与测试流程的改进、Telemetry的推广以及Windows支持的进展。通过讨论，明确了具体的优化方向和实施步骤，并制定了相应的后续行动计划。</p>',8)])])}const _=e(r,[["render",a]]);export{g as __pageData,_ as default};
